    CDenseMatrix Fock_hess_T (natoms, 6);

    Fock_hess_T.zero();

    for (int64_t gpu_id = 0; gpu_id < num_gpus_per_node; gpu_id++)
    {
        for (int64_t a = 0; a < natoms; a++)
        {
            for (int64_t d = 0; d < 6; d++)
